import React, { useState, useEffect } from 'react';
import {
  Paper,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Box,
  Chip,
  Grid,
  Card,
  CardContent,
  Alert
} from '@mui/material';
import {
  Add,
  Edit,
  Delete,
  Save,
  Cancel
} from '@mui/icons-material';
import { realChecklistService } from '../../services/realApiService';

const ChecklistsManagement = () => {
  const [checklists, setChecklists] = useState([]);
  const [areas, setAreas] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [editingChecklist, setEditingChecklist] = useState(null);
  const [newChecklist, setNewChecklist] = useState({
    name: '',
    description: '',
    area_id: '',
    project_id: '',
    iatf_code: '',
    questions: []
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Cargar checklists y áreas reales
  const loadData = async () => {
    try {
      setLoading(true);
      const [checklistsResponse, areasResponse] = await Promise.all([
        realChecklistService.getAll(),
        realChecklistService.getAreas()
      ]);
      
      if (checklistsResponse.data.success) {
        setChecklists(checklistsResponse.data.checklists);
      }
      if (areasResponse.data.success) {
        setAreas(areasResponse.data.areas);
      }
    } catch (error) {
      setError('Error cargando datos: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleCreateChecklist = async () => {
    try {
      const response = await realChecklistService.create(newChecklist);
      if (response.data.success) {
        await loadData();
        setOpenDialog(false);
        setNewChecklist({
          name: '',
          description: '',
          area_id: '',
          project_id: '',
          iatf_code: '',
          questions: []
        });
      }
    } catch (error) {
      setError('Error creando checklist: ' + error.message);
    }
  };

  const handleEditChecklist = (checklist) => {
    setEditingChecklist(checklist);
    setNewChecklist({ ...checklist });
    setOpenDialog(true);
  };

  const handleUpdateChecklist = async () => {
    try {
      const response = await realChecklistService.update(editingChecklist.id, newChecklist);
      if (response.data.success) {
        await loadData();
        setOpenDialog(false);
        setEditingChecklist(null);
      }
    } catch (error) {
      setError('Error actualizando checklist: ' + error.message);
    }
  };

  const handleDeleteChecklist = async (id) => {
    if (window.confirm('¿Estás seguro de que quieres eliminar este checklist?')) {
      try {
        const response = await realChecklistService.delete(id);
        if (response.data.success) {
          await loadData();
        }
      } catch (error) {
        setError('Error eliminando checklist: ' + error.message);
      }
    }
  };

  const handleSaveChecklist = () => {
    if (editingChecklist) {
      handleUpdateChecklist();
    } else {
      handleCreateChecklist();
    }
  };

  const addQuestion = () => {
    setNewChecklist(prev => ({
      ...prev,
      questions: [
        ...prev.questions,
        {
          id: `q${Date.now()}`,
          type: 'boolean',
          text: '',
          image: null
        }
      ]
    }));
  };

  const updateQuestion = (questionId, field, value) => {
    setNewChecklist(prev => ({
      ...prev,
      questions: prev.questions.map(q =>
        q.id === questionId ? { ...q, [field]: value } : q
      )
    }));
  };

  const removeQuestion = (questionId) => {
    setNewChecklist(prev => ({
      ...prev,
      questions: prev.questions.filter(q => q.id !== questionId)
    }));
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">
          Gestión de Checklists
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => {
            setEditingChecklist(null);
            setNewChecklist({
              name: '',
              description: '',
              area_id: '',
              project_id: '',
              iatf_code: '',
              questions: []
            });
            setOpenDialog(true);
          }}
        >
          Nuevo Checklist
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Nombre</TableCell>
              <TableCell>Área</TableCell>
              <TableCell>Código IATF</TableCell>
              <TableCell>Preguntas</TableCell>
              <TableCell>Acciones</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={5} align="center">
                  Cargando checklists...
                </TableCell>
              </TableRow>
            ) : checklists.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} align="center">
                  No hay checklists creados. Crea el primer checklist.
                </TableCell>
              </TableRow>
            ) : (
              checklists.map((checklist) => (
                <TableRow key={checklist.id}>
                  <TableCell>{checklist.name}</TableCell>
                  <TableCell>
                    <Chip label={checklist.area_name || 'Sin área'} size="small" />
                  </TableCell>
                  <TableCell>{checklist.iatf_code}</TableCell>
                  <TableCell>{checklist.questions?.length || 0}</TableCell>
                  <TableCell>
                    <IconButton
                      color="primary"
                      onClick={() => handleEditChecklist(checklist)}
                    >
                      <Edit />
                    </IconButton>
                    <IconButton
                      color="error"
                      onClick={() => handleDeleteChecklist(checklist.id)}
                    >
                      <Delete />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Diálogo para crear/editar checklist */}
      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          {editingChecklist ? 'Editar Checklist' : 'Crear Nuevo Checklist'}
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Nombre del Checklist"
                value={newChecklist.name}
                onChange={(e) => setNewChecklist(prev => ({ ...prev, name: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Código IATF"
                value={newChecklist.iatf_code}
                onChange={(e) => setNewChecklist(prev => ({ ...prev, iatf_code: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Área</InputLabel>
                <Select
                  value={newChecklist.area_id || ''}
                  label="Área"
                  onChange={(e) => setNewChecklist(prev => ({ ...prev, area_id: e.target.value }))}
                >
                  {areas.map(area => (
                    <MenuItem key={area.id} value={area.id}>
                      {area.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Proyecto"
                value={newChecklist.project_id || ''}
                onChange={(e) => setNewChecklist(prev => ({ ...prev, project_id: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Descripción"
                multiline
                rows={2}
                value={newChecklist.description || ''}
                onChange={(e) => setNewChecklist(prev => ({ ...prev, description: e.target.value }))}
              />
            </Grid>
          </Grid>

          <Box sx={{ mt: 3 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
              <Typography variant="h6">Preguntas</Typography>
              <Button onClick={addQuestion} startIcon={<Add />}>
                Agregar Pregunta
              </Button>
            </Box>

            {newChecklist.questions.map((question, index) => (
              <Card key={question.id} sx={{ mb: 2 }}>
                <CardContent>
                  <Grid container spacing={2} alignItems="center">
                    <Grid item xs={12} sm={5}>
                      <TextField
                        fullWidth
                        label={`Pregunta ${index + 1}`}
                        value={question.text}
                        onChange={(e) => updateQuestion(question.id, 'text', e.target.value)}
                      />
                    </Grid>
                    <Grid item xs={12} sm={3}>
                      <FormControl fullWidth>
                        <InputLabel>Tipo de respuesta</InputLabel>
                        <Select
                          value={question.type}
                          label="Tipo de respuesta"
                          onChange={(e) => updateQuestion(question.id, 'type', e.target.value)}
                        >
                          <MenuItem value="boolean">Sí/No</MenuItem>
                          <MenuItem value="number">Numérico</MenuItem>
                          <MenuItem value="text">Texto</MenuItem>
                          <MenuItem value="photo">Foto</MenuItem>
                        </Select>
                      </FormControl>
                    </Grid>
                    <Grid item xs={12} sm={3}>
                      <Button
                        fullWidth
                        variant="outlined"
                        component="label"
                      >
                        Subir Imagen
                        <input type="file" hidden accept="image/*" />
                      </Button>
                    </Grid>
                    <Grid item xs={12} sm={1}>
                      <IconButton
                        color="error"
                        onClick={() => removeQuestion(question.id)}
                      >
                        <Delete />
                      </IconButton>
                    </Grid>
                  </Grid>
                </CardContent>
              </Card>
            ))}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)} startIcon={<Cancel />}>
            Cancelar
          </Button>
          <Button 
            onClick={handleSaveChecklist} 
            variant="contained" 
            startIcon={<Save />}
          >
            {editingChecklist ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ChecklistsManagement;
